-- ============================================================================ 
-- 015 材料入物品模板表（id 段 700001..700041 共 41 种，item_type=4）
--
-- 为什么要这张表：任务编辑器的奖励下拉、以及校验器的"奖励物品必须存在于模板表"这一条，
-- 判据都是 Game_HunduShijie_ItemTemplate。材料此前只活在客户端 MaterialDatabase 里，
-- 于是"奖励可关联所有游戏物品"这句话对材料不成立。
--
-- 为什么是 700000+序号 而不是原来的 10001/20001/…：老号和装备（10001-10013）、
-- 丹药（50001/50002）、宝石（60001-60005）、五行入门任务（90001-90005）在同一个整数空间硬撞，
-- ItemCatalog 里"装备优先"那条回退就是在吞这个冲突。新段与秘籍段（800000+技能id）同构：段即语义。
--
-- 数据源：HundunWorld/Source/Game/Equipment/Material/MaterialData.cs（本文件由它生成，改材料两边一起改）。
-- element 按该列自己的注释写（0金1木2水3火4土5无）；注意这**不是**战斗侧的 0=无,1金…5土。
-- 幂等：每条先 IF EXISTS 再 UPDATE/INSERT，UPDATE 分支写全**内容列**（只改 INSERT 会静默丢数据）。
-- UPDATE 有意不碰的 6 列：item_id（主键/定位）、create_time（已存在那行的创建时间是现场事实）、
-- GameId/AreaId/ServerId/GameUserId（多租户归属键——若某 id 已被别的租户占用，写 0 等于悄悄抢归属，
-- 这种情况要让自检暴露出来而不是被 UPDATE 抹平）。
-- 入库前先跑一次核验（只读，不碰库）：python scripts/verify-quest-material-seed.py
-- ============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

SET IDENTITY_INSERT dbo.Game_HunduShijie_ItemTemplate ON;

-- 铁矿石（原 id 10001）
IF EXISTS (SELECT 1 FROM dbo.Game_HunduShijie_ItemTemplate WHERE item_id = 700001)
    UPDATE dbo.Game_HunduShijie_ItemTemplate SET item_name = N'铁矿石', description = N'最基础的金属矿石，蕴含微弱的金属性能量', item_type = 4, sub_type = 0, base_quality = 0, rarity = 1, element = 0, material_grade = 1, level_require = 1, realm_require = 0, profession_limit = '', max_stack = 999, drop_rate = 0, source_type = 1, source_detail = '', base_attributes = N'', random_attributes = N'', random_attr_count = '', gem_slot_rates = '', synthesis_recipe = N'', inherit_rate = '', element_bonus = 1.00, element_penalty = 1.00, bind_type = 1, sell_price = 1, buy_price = 0, icon_path = N'', model_path = N'', use_effect = N'', can_trade = 1, can_destroy = 1, is_unique = 0, valid_days = 0, update_time = GETUTCDATE(), IsValid = 1 WHERE item_id = 700001;
ELSE
    INSERT INTO dbo.Game_HunduShijie_ItemTemplate (item_id, item_name, description, item_type, sub_type, base_quality, rarity, element, material_grade, level_require, realm_require, profession_limit, max_stack, drop_rate, source_type, source_detail, base_attributes, random_attributes, random_attr_count, gem_slot_rates, synthesis_recipe, inherit_rate, element_bonus, element_penalty, bind_type, sell_price, buy_price, icon_path, model_path, use_effect, can_trade, can_destroy, is_unique, valid_days, create_time, update_time, IsValid, GameId, AreaId, ServerId, GameUserId)
    VALUES (700001, N'铁矿石', N'最基础的金属矿石，蕴含微弱的金属性能量', 4, 0, 0, 1, 0, 1, 1, 0, '', 999, 0, 1, '', N'', N'', '', '', N'', '', 1.00, 1.00, 1, 1, 0, N'', N'', N'', 1, 1, 0, 0, GETUTCDATE(), GETUTCDATE(), 1, 0, 0, 0, '00000000-0000-0000-0000-000000000000');

