SET IDENTITY_INSERT dbo.Game_HunduShijie_ItemTemplate OFF;

-- 自检 1：材料行数必须等于客户端表条数（少一条就是解析/替换漏了）。
IF (SELECT COUNT(*) FROM dbo.Game_HunduShijie_ItemTemplate WHERE item_type = 4) <> 41
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR(N'015 种子：item_type=4 的行数与客户端材料表不一致，整批回滚。', 16, 1) WITH NOWAIT;
    RETURN;
END;

-- 自检 2：700000 段内 id 唯一。
IF EXISTS (SELECT item_id FROM dbo.Game_HunduShijie_ItemTemplate GROUP BY item_id HAVING COUNT(*) > 1)
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR(N'015 种子：物品表出现重复 item_id，整批回滚。', 16, 1) WITH NOWAIT;
    RETURN;
END;

-- 自检 3：名字不能空（奖励下拉与背包都要用它）。
IF EXISTS (SELECT 1 FROM dbo.Game_HunduShijie_ItemTemplate WHERE item_type = 4 AND LTRIM(RTRIM(item_name)) = '')
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR(N'015 种子：有材料没有名字，整批回滚。', 16, 1) WITH NOWAIT;
    RETURN;
END;

COMMIT TRANSACTION;

SELECT COUNT(*) AS material_rows, MIN(item_id) AS min_id, MAX(item_id) AS max_id
FROM dbo.Game_HunduShijie_ItemTemplate WHERE item_type = 4;
